async function generateAIDrafts(form) {
 if(aiState.busy)throw new Error('An AI request is already running.');
 if(!aiState.config||!aiState.session)throw new Error('Connect and sign in to the AI gateway first.');
 if(aiState.session.expiresAt<=Date.now()){clearAuthenticatedContext();render();throw new Error('AI sign-in expired. Sign in again.');}
 const f=new FormData(form),p=project(),selected=f.getAll('sources');
 const excerpts=Object.fromEntries(selected.map(id=>[id,String(f.get('excerpt-'+id)??'').trim()]));const sources=selected.map(id=>{const s=p.sources.find(s=>s.id===id&&!s.archived&&s.origin?.access!=='lost'),r=s?.revisions.at(-1);if(!r)throw new Error('A selected source is unavailable.');const excerpt=excerpts[id];if(excerpt&&!r.content.includes(excerpt))throw new Error('A selected passage must exactly match its original source text.');if(!excerpt&&r.content.length>AI.AI_LIMITS.sourceCharacters)throw new Error(`${s.title} is too long for one request. Choose an exact passage of up to ${AI.AI_LIMITS.sourceCharacters.toLocaleString()} characters.`);return {sourceId:s.id,revisionId:r.id,title:s.title,content:excerpt||r.content};});
 const consent=f.has('consent');
 const task=f.get('task')||'extract_handbook',provider=f.get('provider')||'openai',recordRefs=f.getAll('recordRefs').map(value=>{const [kind,id]=value.split(':');return L.reference(p,kind,id);}),taskContext={role,allowedRoles:D.activeRoles(p),scope:contextFor(lifecycleUI),records:recordRefs.map(l=>{const r=L.ref(p,l.kind,l.id,l.revision);return {...l,title:r.title,description:(l.kind==='requirements'?L.requirementText(p,r):F.canonical(r.data))+'\nScope: '+F.canonical(r.scope)};})},question=task==='extract_handbook'?'':String(f.get('prompt')||AI.DELIVERY_AI_TASKS[task]?.label||'');const request=AI.createAIRequest({task,provider,taskContext,question,sources,projectTitle:p.name,consent,projectId:C.connection(p.id)?p.id:undefined});
 aiState.task=task;aiState.provider=provider;aiState.recordIds=f.getAll('recordRefs');aiState.prompt=f.get('prompt');
 aiState.busy=true;aiState.selectedIds=selected;aiState.excerpts=excerpts;aiState.consent=consent;aiState.status=`Sending ${sources.length} selected source revision(s) to the configured AI gateway…`;aiState.controller=new AbortController();render();
 try {
  const output=await AI.runAI({...aiState.config,accessToken:aiState.session.accessToken,request,signal:aiState.controller.signal});
  if(current!==p.id){aiState.status='Generation finished after the project changed. Open the original project and run again.';return;}
  let runId;const m=output.metadata;
  await commit(p=>{runId=D.recordAIRun(p,{id:m.runId,metrics:{latencyMs:m.latencyMs??0,usage:m.usage??null},task,provider:m.provider,model:m.model,promptVersion:m.promptVersion,schemaVersion:m.schemaVersion,inputHash:m.inputHash,at:m.at,sourceRefs:sources.map(({sourceId,revisionId})=>({sourceId,revisionId})),draftIds:[]}).id;});
  aiState.result={projectId:p.id,runId,recordRefs,taskContext,task,candidateStates:[],sources:sources.map(({sourceId,revisionId})=>({sourceId,revisionId})),output,behaviorStates:[],questionStates:[],sectionStates:[]};
  aiState.status='Suggestions are ready. Review the original passages before saving drafts.';
 } catch(error) {if(error.status===401||error.code==='auth_required')clearAuthenticatedContext();aiState.status=error.message;throw error;}
 finally {aiState.busy=false;aiState.controller=null;render();}
}

