  modal('Record the owner’s interpretation',`<h3>${esc(r.title)}</h3><div class="diff"><section><span>EXISTING AGREEMENT</span>${r.base?ruleSummary(r.base,esc):'<p>No existing rule selected</p>'}</section><section><span>STATEMENT</span><blockquote>${esc(r.evidence.quote)}</blockquote></section></div>`+memberField(p,'Decision recorded by','reviewerId',person||p.members.find(m=>m.role==='Product')?.id)+field('Owner decision and reasoning','resolution',r.resolution,'textarea')+`<label>Next step<select name="resolutionAction" id="resolution-action">${options([['keep','Record clarification · keep existing agreement'],['defer','Keep unresolved · more information needed'],...(r.base?[['propose','Create a reviewed rule proposal']]:[]),['draft','Create a new rule draft']])}</select></label><div id="resolution-rule-fields" hidden>${ruleFields(base,{field,esc,options,project:p})}</div><p class="small-note">Proposals and new drafts require a separate approval. A statement never silently overwrites an agreement.</p>`+submit('Save owner decision'),async f=>{const action=f.get('resolutionAction'),details=action==='propose'||action==='draft'?ruleDetailsFromForm(f,base):undefined;await commit(p=>R.resolveStatement(p,r.id,{reviewerId:f.get('reviewerId'),resolution:f.get('resolution'),action,details}));notify('Interpretation preserved. Review any new rule proposal or draft separately.');});
  const update=()=>{const active=['propose','draft'].includes(document.querySelector('#resolution-action').value),container=document.querySelector('#resolution-rule-fields');container.hidden=!active;container.querySelectorAll('input,textarea,select').forEach(input=>input.disabled=!active);};document.querySelector('#resolution-action').onchange=update;update();
