function rotatePassphrase(){const p=project();if(!S.storageState(p.id).protected)throw new Error('Protect this project first.');modal('Rotate the known project passphrase',field('Current passphrase','known','','password')+passphraseFields()+'<p>The current file is retained as an encrypted backup under the old passphrase. Save the new master afterward and share its new passphrase separately. Previously downloaded files remain readable with their old secret.</p>'+submit('Create backup and rotate'),async f=>{const result=await S.rotateProjectPassphrase(p.id,f.get('known'),checkPassphrase(f));download(basename(p)+'-before-key-rotation.relay',result.backup);await refreshCache();render();notify('Recovery re-encrypted. Save the new master file before distributing the new passphrase.');});}
function recoveryBackup(){const p=project();modal('Enable recovery for the active project',field('Current project passphrase','known','','password')+'<p>This upgrades the active encrypted file. One recovery secret will open subsequent saved versions until recovery is replaced. Old snapshots still need their old secret. Earlier app versions cannot open this format.</p>'+submit('Create active-file recovery'),async f=>{const backup=await S.createRecoveryBackup(p.id,f.get('known'));await refreshCache();modal('Keep this recovery secret separately',`<p>Save the upgraded master now. Both the normal passphrase and this secret can open its later saved revisions. Losing both is unrecoverable.</p><label for="recovery-secret">Recovery secret</label><input id="recovery-secret" readonly value="${esc(backup.secret)}">`+submit('Download upgraded master and secret'),async()=>{download(basename(p)+'.relay',backup.file);download(basename(p)+'-recovery-secret.txt','Product Relay recovery secret\n'+backup.secret+'\nKeep separately from the project file.');closeDialog();render();});});}
