document.addEventListener('change',async e=>{
 try{
  if(e.target.closest('#ai-generation-form')){const form=e.target.closest('form'),f=new FormData(form);aiState.selectedIds=f.getAll('sources');aiState.consent=f.has('consent');aiState.task=f.get('task');aiState.provider=f.get('provider');aiState.recordIds=f.getAll('recordRefs');aiState.prompt=f.get('prompt');}
  if(e.target.dataset.lcScope){lifecycleUI[e.target.dataset.lcScope]=e.target.value;knowledgeState.context=null;knowledgeState.result=null;render();}
  if(e.target.id==='lc-ownership'||e.target.id==='global-ownership'){lifecycleUI.ownership=e.target.value;render();}
  if(e.target.id==='candidate-build'){lifecycleUI.build=e.target.value;render();}
  if(e.target.id==='project-picker'){knowledgeState.context=null;knowledgeState.result=null;current=e.target.value;view='overview';version='';query='';showArchived=false;role='Everyone';person='';render();}
  if(e.target.id==='perspective-picker'){knowledgeState.context=null;knowledgeState.result=null;const [kind,value]=e.target.value.split(':');person=kind==='member'?value:'';role=person?project().members.find(m=>m.id===person).role:value;render();}
  if(e.target.id==='version-picker'||e.target.id==='search-version'){version=e.target.value;render();}
  if(e.target.id==='merge-file'){const file=e.target.files[0];e.target.value='';if(file)await receiveMergeFile(file);}
  if(e.target.id==='project-file'){const file=e.target.files[0];e.target.value='';if(file)await receiveFile(file);}
  if(e.target.id==='source-file'){const file=e.target.files[0];e.target.value='';if(!file)return;const form=document.querySelector('#modal-form');if(!form?.elements.content)return;if(importBusy)throw new Error('A document import is already running. Wait or close the dialog to cancel it.');const preview=document.querySelector('#import-preview');sourceImport=null;importBusy=true;importController=new AbortController();const picker=form.querySelector('[data-action="pick-source"]');if(picker)picker.disabled=true;const save=form.querySelector('[type="submit"]');save.disabled=true;try{if(preview)preview.textContent='Reading document…';const result=await extractDocument(file,{signal:importController.signal,onProgress:message=>{if(preview?.isConnected)preview.textContent=typeof message==='string'?message:`Reading page ${message.page} of ${message.total}…`;}});if(!form.isConnected||!form.closest('dialog')?.open)return;sourceImport=result;form.elements.content.value=result.content;if(form.elements.title&&!form.elements.title.value)form.elements.title.value=result.title;if(form.elements.kind&&result.kind==='Walkthrough')form.elements.kind.value='Walkthrough';const duplicate=findDuplicateDocument(project(),result);if(preview)preview.innerHTML=importPreview(result,duplicate);}catch(error){if(preview?.isConnected)preview.textContent=error.message;throw error;}finally{importBusy=false;importController=null;if(save.isConnected)save.disabled=false;if(picker?.isConnected)picker.disabled=false;}}
 }catch(error){notify(error.message);}
});
document.addEventListener('cancel',e=>{if(e.target.id==='modal'){importController?.abort();sourceImport=null;}},true);
document.addEventListener('input',e=>{if(e.target.closest('#ai-generation-form')&&e.target.name.startsWith('excerpt-'))aiState.excerpts[e.target.name.slice(8)]=e.target.value;});
document.addEventListener('submit',async e=>{if(e.target.id==='knowledge-form'){e.preventDefault();try{const f=new FormData(e.target);knowledgeState.context=K.retrieveKnowledge(project(),f.get('question'),{versionId:f.get('versionId'),role,mode:f.get('mode')||'agreement',releaseId:f.get('releaseId')||'',environmentId:f.get('environmentId')||'',audience:f.get('audience')||'',build:f.get('build')||'',flag:f.get('flag')||''});knowledgeState.result=null;render();}catch(error){notify(error.message);}return;}if(e.target.id==='merge-form'){e.preventDefault();const submitButton=e.target.querySelector('[type="submit"]');if(submitButton.disabled)return;submitButton.disabled=true;try{const f=new FormData(e.target),comparison=fileComparison,original=D.clone(project()),choices=Object.fromEntries(comparison.differences.map(d=>[d.id,f.get('choice-'+d.id)]));const merged=await F.mergeProjectCopies(original,comparison,choices,{includeApproved:f.has('includeApproved'),reviewerId:f.get('reviewerId'),note:f.get('note')});await commit(p=>{if(F.canonical(p)!==F.canonical(original))throw new Error('Master changed during merge. Compare again.');Object.assign(p,merged);for(const r of L.list(p,'returns').filter(r=>r.status==='received'&&r.data.receivedHash===comparison.incomingHash))L.editRecord(p,'returns',r.id,{status:'merged',data:{mergedAt:new Date().toISOString()}},f.get('reviewerId'),f.get('note'));});fileComparison=null;render();notify('Reviewed edits merged. Save the updated master file before sharing.');}catch(error){const node=document.querySelector('#merge-error');if(node)node.textContent=error.message;notify(error.message);}finally{if(submitButton.isConnected)submitButton.disabled=false;}return;}if(e.target.id==='ai-generation-form'){e.preventDefault();try{await generateAIDrafts(e.target);}catch(error){notify(error.message);}return;}if(e.target.id==='search-form'){e.preventDefault();query=new FormData(e.target).get('query');render();}});
try{await refreshCache();legacyCount=(await S.legacyProjects()).length;render();}catch(error){app.innerHTML=`<div class="storage-error"><h1>Recovery storage could not open</h1><p>${esc(error.message)}</p><p>Open a browser with site storage enabled. Your .relay project files remain available on disk.</p></div>`;}

window.addEventListener('beforeunload',event=>{if(projects.some(p=>S.storageState(p.id).cacheStale)){event.preventDefault();event.returnValue='';}});
